package in.anumati.platform.compliance; import in.anumati.platform.application.ApplicationRecord; import in.anumati.platform.business.BusinessProfile; import in.anumati.platform.regulatory.Approval; import in.anumati.platform.regulatory.RegulatorySource; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="compliance_obligations") public class ComplianceObligation { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="business_profile_id",nullable=false) private BusinessProfile businessProfile; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="application_id") private ApplicationRecord application; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="approval_id") private Approval approval; @Column(nullable=false,length=250) private String name; @Column(nullable=false,length=200) private String authority; @Column(length=1500) private String description; @Column(name="due_date",nullable=false) private LocalDate dueDate; @Column(name="reminder_days",nullable=false) private int reminderDays; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ComplianceFrequency frequency; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ComplianceStatus status; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="source_id") private RegulatorySource source; private Instant completedAt; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; protected ComplianceObligation(){} public ComplianceObligation(BusinessProfile p,ApplicationRecord a,Approval approval,String name,String authority,String desc,LocalDate due,int rem,ComplianceFrequency freq,RegulatorySource source){id=UUID.randomUUID();businessProfile=p;application=a;this.approval=approval;this.name=name;this.authority=authority;description=desc;dueDate=due;reminderDays=rem;frequency=freq;this.source=source;createdAt=Instant.now();updatedAt=createdAt;refresh();} public void refresh(){if(status==ComplianceStatus.COMPLETED)return;LocalDate today=LocalDate.now();if(dueDate.isBefore(today))status=ComplianceStatus.OVERDUE;else if(!today.isAfter(dueDate.minusDays(reminderDays)))status=ComplianceStatus.DUE;else status=ComplianceStatus.UPCOMING;updatedAt=Instant.now();} public void complete(){status=ComplianceStatus.COMPLETED;completedAt=Instant.now();updatedAt=completedAt;} public boolean isRecurring(){return frequency!=ComplianceFrequency.ONE_TIME;} public LocalDate nextDueDate(){return switch(frequency){case MONTHLY -> dueDate.plusMonths(1);case QUARTERLY -> dueDate.plusMonths(3);case HALF_YEARLY -> dueDate.plusMonths(6);case ANNUAL -> dueDate.plusYears(1);case ONE_TIME -> dueDate;};} public UUID getId(){return id;}public BusinessProfile getBusinessProfile(){return businessProfile;}public ApplicationRecord getApplication(){return application;}public Approval getApproval(){return approval;}public String getName(){return name;}public String getAuthority(){return authority;}public String getDescription(){return description;}public LocalDate getDueDate(){return dueDate;}public int getReminderDays(){return reminderDays;}public ComplianceFrequency getFrequency(){return frequency;}public ComplianceStatus getStatus(){return status;}public RegulatorySource getSource(){return source;}public Instant getCompletedAt(){return completedAt;}public Instant getUpdatedAt(){return updatedAt;} }
